import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"初始化","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/initialization.md","filePath":"projects/lotus-plugin/docs/initialization.md"}'),l={name:"projects/lotus-plugin/docs/initialization.md"};function n(s,e,d,p,c,r){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><h2 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h2><p>全局配置样例在 <code>config/global.example.yaml</code>。用户 profile 样例在 <code>config/profile.example.yaml</code>。</p><p>插件加载时如果没有 <code>config/global.yaml</code>，会自动按默认配置创建，不需要手动复制样例文件。已安装锅巴插件时，可以在锅巴面板里修改全局配置。</p><p>运行时数据会写入：</p><ul><li><code>data/users/&lt;qq&gt;.yaml</code></li><li><code>data/users/&lt;qq&gt;-2.yaml</code></li><li><code>data/python/</code></li><li><code>data/tools/</code></li><li><code>data/atlas/</code></li></ul><p>这些目录不应提交。</p><h2 id="签到环境" tabindex="-1">签到环境 <a class="header-anchor" href="#签到环境" aria-label="Permalink to &quot;签到环境&quot;">​</a></h2><p>发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#初始化签到环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>会检查并准备：</p><ul><li><code>data/python/venv</code></li><li><code>MihoyoBBSTools</code> 子模块依赖</li><li><code>data/python/test_nine_venv</code></li><li><code>test_nine</code> 服务依赖</li><li><code>data/test_nine/model</code></li><li>BBDown、ffmpeg、aria2 工具链</li></ul><p>默认使用 venv，不污染系统 Python。高级用户可以在全局配置里切换为 system Python。</p><h2 id="下载工具" tabindex="-1">下载工具 <a class="header-anchor" href="#下载工具" aria-label="Permalink to &quot;下载工具&quot;">​</a></h2><p>发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#初始化工具环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>会按系统和架构准备 BBDown、ffmpeg、aria2。B 站下载只保留 BBDown 路径，不再提供“是否使用 BBDown”的开关。</p><p>ffmpeg 会下载完整编译包，而不是只拷贝 <code>ffmpeg</code> 一个文件；Windows 会识别 <code>.exe</code>，Linux/macOS 会识别无后缀可执行文件。解压后会把 BBDown、ffmpeg、ffprobe、ffplay、aria2c 等可执行文件加入插件工具目录，并在非 Windows 系统上自动补 <code>chmod +x</code>。</p><p>如果下载目录里存在不完整 shared 包、损坏压缩包或 <code>.part</code> 临时文件，初始化会按损坏状态重新下载并修复。</p><p>更多说明见 <a href="./features/tools.html">工具链-BBDown/ffmpeg/aria2</a>。</p>',21)])])}const u=a(l,[["render",n]]);export{m as __pageData,u as default};
